function normalizeSceneAudio(s){const legacy=s.audio&&typeof s.audio==='object'?s.audio:{};let a=s.audioPlan&&typeof s.audioPlan==='object'?s.audioPlan:null;if(!a){const text=String(s.dialogue||'');a={required:!!(text.trim()||legacy.voiceover||legacy.music||(legacy.effects||[]).length),dialogue:text.trim()?[{speakerName:'',speakerId:'',voiceProfileId:'',voiceProfile:'',text,emotion:'',delivery:''}]:[],voiceover:{narratorName:'',narratorId:'',voiceProfileId:'',voiceProfile:'',text:String(legacy.voiceover||''),emotion:'',delivery:''},music:{description:String(legacy.music||''),mood:'',continuityId:'',transition:''},ambience:[],soundEffects:Array.isArray(legacy.effects)?legacy.effects:[]}}a.required=!!a.required;a.dialogue=Array.isArray(a.dialogue)?a.dialogue:[];a.dialogue=a.dialogue.map(x=>({speakerName:'',speakerId:'',voiceProfileId:'',voiceProfile:'',text:'',emotion:'',delivery:'',...(x&&typeof x==='object'?x:{})}));a.voiceover={narratorName:'',narratorId:'',voiceProfileId:'',voiceProfile:'',text:'',emotion:'',delivery:'',...(a.voiceover&&typeof a.voiceover==='object'?a.voiceover:{})};a.music={description:'',mood:'',continuityId:'',transition:'',...(a.music&&typeof a.music==='object'?a.music:{})};a.ambience=Array.isArray(a.ambience)?a.ambience:[];a.soundEffects=Array.isArray(a.soundEffects)?a.soundEffects:[];s.audioPlan=a;s.dialogue=a.dialogue.map(x=>x.text).filter(Boolean).join('\n');s.audio={voiceover:a.voiceover.text,music:a.music.description,effects:a.soundEffects};return a}
