function setTab(tab){activeTab=tab;planNotice=null;renderProject();window.scrollTo(0,0)}
function effectiveScene(s){return{...s,narrativePurpose:s.narrativePurpose??s.purpose??'',visualDescription:s.visualDescription??s.visual??'',referenceAssetIds:Array.isArray(s.referenceAssetIds)?s.referenceAssetIds:Array.isArray(s.assetIds)?s.assetIds:[],camera:String(s.camera||'').trim()||'medium shot, gerakan kamera lembut',lighting:String(s.lighting||'').trim()||'pencahayaan lembut sesuai suasana adegan',audio:s.audio&&typeof s.audio==='object'?s.audio:{voiceover:'',music:'',effects:[]},continuityIn:s.continuityIn&&typeof s.continuityIn==='object'?s.continuityIn:{},continuityOut:s.continuityOut&&typeof s.continuityOut==='object'?s.continuityOut:{}}}
