function promptExport(project,platform,scene,selectedAssets,promptText){const pack=buildSceneProduction(project,platform,scene,selectedAssets);if(promptText!==undefined)pack.prompt=promptText;return pack}
function makePrompt(s,plat,d,project=current){const source=project||{title:'',platform:d.productionSettings?.platform||'flow',data:d},pack=buildSceneProduction(source,plat,s),scene=pack.scene,brief=pack.projectBrief,story=pack.storyPlan;const describe=items=>items.map(item=>[item.role?`${item.name} (${item.role})`:item.name,item.description,item.identity,item.appearance].filter(Boolean).join(': ')).filter(Boolean).join('; '),storyGuide=[story.title,story.logline,story.opening,story.conflict,story.development,story.ending].filter(Boolean).join(' → ');const parts=[plat.prompt,storyGuide?`Rencana cerita: ${storyGuide}.`:'',`Panduan cerita: gaya ${brief.visualStyle||'natural'}.`,brief.characterNotes?`Konsistensi karakter: ${brief.characterNotes}`:'',brief.locationNotes&&!uniqueText([scene.location,scene.time,pack.location?.name]).some(value=>value.toLocaleLowerCase()===String(brief.locationNotes).trim().toLocaleLowerCase())?`Konsistensi dunia/lokasi: ${brief.locationNotes}`:'',brief.keyMessage?`Pesan cerita: ${brief.keyMessage}`:'',describe(pack.characters)?`Karakter yang harus dipertahankan: ${describe(pack.characters)}.`:'',pack.products.length?`Produk yang harus dipertahankan: ${describe(pack.products)}.`:'',pack.location&&describe([pack.location])&&!(String(scene.location||'').trim().toLocaleLowerCase()===String(pack.location.name||'').trim().toLocaleLowerCase()&&![pack.location.description,pack.location.identity,pack.location.appearance].some(Boolean))?`Lokasi yang harus dipertahankan: ${describe([pack.location])}.`:'',`Adegan: ${scene.title||'Momen cerita'}.`,scene.narrativePurpose?`Tujuan: ${scene.narrativePurpose}`:'',scene.visualDescription?`Visual: ${scene.visualDescription}`:'',`Lokasi dan waktu: ${uniqueText([scene.location,scene.time,pack.location?.name]).join(', ')||brief.locationNotes||'sesuai kebutuhan cerita'}.`,`Aksi: ${scene.action||'aksi karakter utama'}.`,scene.expression?`Ekspresi: ${scene.expression}`:'',`Framing dan kamera: ${scene.camera}.`,`Pencahayaan: ${scene.lighting}.`,`Dialog/narasi: ${scene.audioPlan?.dialogue?.map(x=>x.text).filter(Boolean).join(' / ')||'tanpa dialog'}.`,`Durasi target klip ini: ${scene.duration||brief.targetDuration||'5 detik'}.`,`Rencana video: target proyek ${pack.durationSummary.projectTarget||'belum ditentukan'}; total durasi scene ${pack.durationSummary.sceneTotalSeconds===null?'belum lengkap':`${pack.durationSummary.sceneTotalSeconds} detik`}.${pack.durationSummary.warning?` ${pack.durationSummary.warning}`:''}`,'Batas durasi per klip bergantung pada model video yang dipilih di platform.',audioPromptLines(pack),pack.selectedAssets.length?`Aset referensi yang perlu diunggah secara manual: ${pack.selectedAssets.map(a=>`${a.name} (${a.type||a.category||'referensi'})`).join('; ')}.`:'Belum ada aset yang ditautkan ke adegan ini.'];return parts.filter(Boolean).map(cleanPromptText).join('\n\n')}
function estimateSpeechSeconds(text){const words=String(text||'').trim().split(/\s+/).filter(Boolean).length;return words?Math.ceil(words/2.5):0}
