function audioPromptLines(pack){const s=pack.scene,a=s.audioPlan||{},lines=[],estimate=audioSpeechEstimate(s);if(!a.required)return 'Rencana audio: tidak diperlukan untuk adegan ini.';lines.push('Rencana audio untuk produksi manual; audio belum dibuat dan lip-sync tidak dijamin.');for(const d of a.dialogue||[])if(d.text)lines.push(`Dialog karakter ${d.speakerName||d.speakerId||'pembicara belum ditentukan'}: “${d.text}”. Profil suara tetap: ${d.voiceProfileId||'ID belum ditentukan'}${d.voiceProfile?` (${d.voiceProfile})`:''}; emosi ${d.emotion||'natural'}; penyampaian ${d.delivery||'natural'}.`);if(a.voiceover?.text)lines.push(`Voice-over/narasi oleh ${a.voiceover.narratorName||a.voiceover.narratorId||'narator belum ditentukan'}: “${a.voiceover.text}”. Profil suara tetap: ${a.voiceover.voiceProfileId||'ID belum ditentukan'}${a.voiceover.voiceProfile?` (${a.voiceover.voiceProfile})`:''}; emosi ${a.voiceover.emotion||'natural'}; penyampaian ${a.voiceover.delivery||'natural'}.`);if(a.ambience?.length)lines.push(`Suasana latar: ${a.ambience.join(', ')}.`);if(a.soundEffects?.length)lines.push(`Efek suara: ${a.soundEffects.join(', ')}.`);if(a.music?.description)lines.push(`Musik: ${a.music.description}; mood ${a.music.mood||'belum ditentukan'}; transisi ${a.music.transition||'sesuai kebutuhan'}.`);if(a.music?.continuityId)lines.push(`ID kesinambungan musik: ${a.music.continuityId}.`);if(pack.audioDirector?.continuityNotes)lines.push(`Konsistensi audio antarscene: ${pack.audioDirector.continuityNotes}`);lines.push(`Perkiraan dialog/narasi ${estimate.speechSeconds} detik pada klip ${estimate.clipSeconds??'durasi belum diketahui'} detik${estimate.overLimit?' — teks kemungkinan terlalu panjang, ringkas atau ubah durasi':''}.`);return lines.join(' ')}
function durationSeconds(value){const match=String(value||'').trim().toLowerCase().match(/^(\d+(?:[.,]\d+)?)\s*(detik|det|s|sec|seconds?|menit|mnt|min|minutes?)?$/);if(!match)return null;const amount=Number(match[1].replace(',','.'));if(!Number.isFinite(amount)||amount<=0)return null;return Math.round(amount*(['menit','mnt','min','minute','minutes'].includes(match[2])?60:1))}
function durationPlan(data){const target=data.projectBrief?.targetDuration||data.duration||'',targetSeconds=durationSeconds(target),sceneDurations=(data.scenes||[]).map(scene=>durationSeconds(scene.duration)),known=sceneDurations.filter(value=>value!==null),totalSeconds=known.reduce((sum,value)=>sum+value,0),complete=known.length===sceneDurations.length;return{projectTarget:target,targetSeconds,sceneCount:sceneDurations.length,sceneTotalSeconds:complete?totalSeconds:null,knownSceneSeconds:totalSeconds,allSceneDurationsKnown:complete,matches:targetSeconds!==null&&complete&&targetSeconds===totalSeconds,providerClipLimitSeconds:null,warning:targetSeconds===null?'':!complete?'Isi durasi setiap adegan agar total dapat dibandingkan dengan target proyek.':targetSeconds!==totalSeconds?`Total adegan ${totalSeconds} detik berbeda dari target proyek ${targetSeconds} detik.`:''}}
function durationSummaryText(plan){return `Target proyek: ${plan.projectTarget||'belum ditentukan'} · total scene: ${plan.sceneTotalSeconds===null?'belum lengkap':`${plan.sceneTotalSeconds} detik`}${plan.warning?` · ${plan.warning}`:''}`}
