function linkAssetToScenes(data,assetId,sceneIds){const selected=new Set(sceneIds);for(const scene of data.scenes||[]){const ids=new Set(Array.isArray(scene.referenceAssetIds)?scene.referenceAssetIds:Array.isArray(scene.assetIds)?scene.assetIds:[]);if(selected.has(scene.id))ids.add(assetId);else ids.delete(assetId);scene.assetIds=[...ids];scene.referenceAssetIds=scene.assetIds}return data}
