const packageAudioLabels = {tanpa_audio:'Tanpa audio',dialog:'Dialog',narasi:'Narasi',musik:'Musik',efek:'Efek suara'};
const packageAudioLabelsEn = {tanpa_audio:'no audio',dialog:'dialogue',narasi:'narration',musik:'music',efek:'sound effects'};
const packageRoleLabels = {karakter:'Karakter',produk:'Produk',lokasi:'Lokasi',gaya:'Gaya',bingkai_awal:'Bingkai awal'};
const packageRoleLabelsEn = {karakter:'character',produk:'product',lokasi:'location',gaya:'style',bingkai_awal:'opening frame'};
const packageLabels = {
  id: {heading:'Detail produksi', action:'Aksi', camera:'Kamera', lighting:'Pencahayaan', audio:'Audio', characters:'Tokoh', locations:'Lokasi', references:'Gambar referensi', continuity:n=>`lanjutan dari klip ${n}, pertahankan tokoh, lokasi, dan pencahayaan yang sama`},
  en: {heading:'Production details', action:'Action', camera:'Camera', lighting:'Lighting', audio:'Audio', characters:'Characters', locations:'Location', references:'Reference images', continuity:n=>`continues from clip ${n}, keep the same characters, location and lighting`}
};
