  goal:'Tujuan video', core:'Inti cerita', message:'Pesan utama', camera:'Saran kamera (satu per baris)', assetsNeeded:'Gambar yang perlu diunggah (satu per baris)', characters:'Tokoh dan hubungannya (satu per baris)', locations:'Lokasi dan suasana (satu per baris)',
