function packageTargetSeconds(){const seconds=durationSeconds(current?.data?.duration);return seconds&&seconds>=1&&seconds<=packageMaxSeconds?seconds:null}
function packageAssetName(id){return (current?.data?.assets||[]).find(asset=>asset.id===id)?.name||'gambar tidak ditemukan'}
function packageNames(ids,items){return ids.length?ids.map(id=>esc((items||[]).find(item=>item.id===id)?.name||id)).join(', '):'—'}
function packageRefLabel(ref,pkg){
  const role=esc(packageRoleLabels[ref.role]||ref.role);
  if(ref.kind==='asset')return `${role}: ${esc(packageAssetName(ref.id))}`;
  const requirement=(pkg.image_requirements||[]).find(item=>item.id===ref.id);
  return `${role}: kebutuhan "${esc(requirement?.purpose||ref.id)}"`;
}
function packageAssetWarnings(pkg){
  const known=new Set((current?.data?.assets||[]).map(asset=>asset.id));
  const missing=new Set();
  for(const clip of pkg.clips||[])for(const ref of clip.references||[])if(ref.kind==='asset'&&!known.has(ref.id))missing.add(ref.id);
  for(const requirement of pkg.image_requirements||[])if(requirement.asset_id&&!known.has(requirement.asset_id))missing.add(requirement.asset_id);
  return missing.size?[`${missing.size} gambar yang dipakai paket tidak ada lagi di daftar unggahan. Unggah ulang atau pilih gambar lain sebelum menyimpan.`]:[];
}

// Builds the prompt text for one clip. Structured fields are appended only when the text does not already contain them.
// `missing` lists the English details that are not filled in yet, so the user can see what is still in Indonesian only.
function assemblePromptText(clip,pkg,lang){
  const en=lang==='en', L=packageLabels[lang], base=(en?clip.prompt_en:clip.prompt_final)||'';
  if(!base)return {text:'',missing:[]};
  const lines=[], missing=[], english=clip.en||{};
  const add=(label,value)=>{if(!value)return;lines.push(`- ${label}: ${value}`)};
  const field=(key,label,idValue)=>{if(!en)return add(label,idValue);if(english[key])return add(label,english[key]);if(idValue)missing.push(label)};
  field('action',L.action,clip.action);
  field('camera',L.camera,clip.camera);
  field('lighting',L.lighting,clip.lighting);
  if(clip.audio?.plan&&clip.audio.plan!=='tanpa_audio'){
    const planLabel=en?packageAudioLabelsEn[clip.audio.plan]:packageAudioLabels[clip.audio.plan];
    const text=en?english.audio_text:clip.audio.text;
    if(en&&clip.audio.text&&!english.audio_text)missing.push(L.audio);
    add(L.audio,[planLabel,text].filter(Boolean).join(': '));
  }
  const cast=(ids,items,detailKey,label)=>ids.map(id=>{
    const item=(items||[]).find(entry=>entry.id===id);
    if(!item)return null;
    const detail=en?item[`${detailKey}_en`]:item[detailKey];
    if(en&&item[detailKey]&&!item[`${detailKey}_en`])missing.push(`${label} ${item.name}`);
    return detail?`${item.name} (${detail})`:item.name;
  }).filter(Boolean);
  add(L.characters,cast(clip.characters||[],pkg.characters,'appearance',L.characters).join('; '));
  add(L.locations,cast(clip.locations||[],pkg.locations,'description',L.locations).join('; '));
  const refs=(clip.references||[]).map(ref=>{
    const role=en?packageRoleLabelsEn[ref.role]||ref.role:packageRoleLabels[ref.role]||ref.role;
    if(ref.kind==='asset')return `${role}: ${packageAssetName(ref.id)}`;
    const purpose=(pkg.image_requirements||[]).find(item=>item.id===ref.id)?.purpose||ref.id;
    if(en)missing.push(`${L.references} ${purpose}`);
    return `${role}: ${purpose}`;
  });
  add(L.references,refs.join('; '));
  if(clip.continues_from)lines.push(`- ${L.continuity(clip.continues_from)}`);
  return {text:lines.length?`${base}\n\n${L.heading}:\n${lines.join('\n')}`:base,missing};
}
function packageLanguageGaps(pkg){
  return (pkg.clips||[]).map(clip=>{const {missing}=assemblePromptText(clip,pkg,'en');return missing.length?`klip ${clip.index}: ${[...new Set(missing)].join(', ')}`:null}).filter(Boolean);
}

