function planReviewHtml(){
  const u=understandingState();
  if(!u)return '';
  const d=ensureData(), ready=understandingConfirmed(), stale=understandingStale();
  const suggestions=u.suggestions||[], accepted=u.acceptedSuggestions||[];
  const list=(title,items)=>items?.length?`<div class="pkg-block"><h3>${title}</h3><ul class="pkg-list">${items.map(item=>`<li>${esc(item)}</li>`).join('')}</ul></div>`:'';
  const style=u.recommendedStyle||'';
  const styleBlock=style?`<div class="pkg-block plan-style"><h3>Gaya visual yang direkomendasikan</h3><p><b>${esc(style)}</b> ${d.style===style?'<span class="saved-hint">· sudah dipakai</span>':`<button class="soft-button" id="use-recommended-style" data-style="${esc(style)}"${ready?' disabled':''}>Pakai gaya ini</button>`}</p></div>`:'';
  if(ready){
    const used=accepted.length?`<div class="pkg-block"><h3>Usulan AI yang Anda setujui</h3><ul class="pkg-list">${accepted.map(item=>`<li>${esc(item)}</li>`).join('')}</ul></div>`:'<p class="sub">Tidak ada usulan AI yang Anda setujui. Paket tidak menambahkan tambahan kreatif dari AI.</p>';
    const unused=suggestions.filter(item=>!accepted.includes(item));
    const notUsed=unused.length?`<p class="sub">Usulan AI yang tidak dipakai: ${unused.map(item=>esc(item)).join('; ')}</p>`:'';
    return `<div class="plan-card" id="plan-review"><div class="eyebrow">RENCANA PRODUKSI · DISETUJUI</div><p class="pkg-status uploaded">Rencana sudah Anda setujui</p>${u.goal?`<p class="sub"><b>Tujuan video:</b> ${esc(u.goal)}</p>`:''}<p class="sub"><b>Inti cerita:</b> ${esc(u.core)}</p>${u.message?`<p class="sub"><b>Pesan utama:</b> ${esc(u.message)}</p>`:''}${styleBlock}${list('Tokoh dan hubungannya',u.characters)}${list('Lokasi',u.locations)}${list('Adegan',u.sequence)}${list('Saran kamera',u.camera)}${list('Gambar yang perlu diunggah',u.assetsNeeded)}${used}${notUsed}<div class="draft-actions"><button class="soft-button" id="reopen-understanding">Ubah rencana</button><button class="primary" data-tab="package">Lanjut ke paket produksi →</button></div></div>`;
  }
  const questions=u.questions||[];
  const questionBlock=questions.length?`<div class="pkg-warning plan-questions" role="note"><b>AI perlu tahu sedikit lagi</b><ol>${questions.map(item=>`<li>${esc(item)}</li>`).join('')}</ol><label class="field-label" for="plan-answers">Jawaban singkat Anda (boleh dilewati)</label><textarea id="plan-answers" class="input" rows="3" maxlength="1000"></textarea><div class="draft-actions"><button class="primary" id="answer-questions">Perbarui rencana dengan jawaban ini</button></div></div>`:'';
  const fields=[...understandingTextFields.map(key=>[key,u[key]||'',false]),...understandingListFields.map(key=>[key,(u[key]||[]).join('\n'),true])];
  const inputs=fields.map(([key,value,isList])=>`<label class="pkg-link"><span class="field-label">${esc(understandingTitles[key])}</span><textarea class="input" rows="${isList?3:2}" data-understanding-field="${key}">${esc(value)}</textarea></label>`).join('');
  const suggestionBoxes=suggestions.length
    ? `<fieldset class="pkg-block"><legend class="field-label">${esc(understandingTitles.suggestions)}</legend>${suggestions.map((item,index)=>`<label class="check-row"><input type="checkbox" data-accept-suggestion="${index}"${accepted.includes(item)?' checked':''}> <span>${esc(item)}</span></label>`).join('')}</fieldset>`
    : '';
  const warning=stale?`<p class="pkg-warning" role="alert">⚠ Ide sudah berubah sejak rencana disetujui. Periksa lalu setujui ulang.</p>`:'';
  return `<div class="plan-card" id="plan-review"><div class="eyebrow">RENCANA PRODUKSI · PERIKSA DULU</div><h2>Periksa rencana AI</h2><p class="sub">Ubah yang tidak sesuai. Rencana baru dipakai setelah Anda setujui. Jika tidak ada yang ingin diubah, langsung setujui.</p>${warning}${questionBlock}${styleBlock}${inputs}${suggestionBoxes}<div class="draft-actions"><button class="primary" id="confirm-understanding">Setujui rencana ini</button></div></div>`;
}
