function toggleSuggestion(index,checked){
  const u=understandingState();
  if(!u||understandingConfirmed())return;
  const item=(u.suggestions||[])[index];
  if(item===undefined)return;
  const others=(u.acceptedSuggestions||[]).filter(text=>text!==item);
  u.acceptedSuggestions=checked?[...others,item]:others;
  scheduleSave();
}
async function confirmUnderstanding(){
  const u=understandingState();
  if(!u||!String(u.core||'').trim()){toast('Isi inti cerita dulu sebelum mengonfirmasi.');return}
  const previous=u;
  current.data.understanding={...u,acceptedSuggestions:u.acceptedSuggestions||[],status:'confirmed',ideaAtConfirm:current.idea||''};
  let saved=false;
  try{saved=await saveNow()}catch{saved=false}
  if(saved){
    toast('Pemahaman dikonfirmasi. Anda sekarang bisa membuat paket produksi.');
  }else{
    // The status only counts once the server has stored it. Until then the summary stays unconfirmed.
    current.data.understanding={...previous,status:'draft'};
    setPlanNotice('error','Pemahaman belum tersimpan, jadi belum dikonfirmasi. Tekan "Ulangi simpan" lalu konfirmasi lagi.');
  }
  renderTab();
}
