  const people=(title,items)=>items?.length?`<div class="pkg-block"><h3>${title}</h3><ul class="pkg-list">${items.map(item=>`<li><b>${esc(item.name)}</b>${item.role?` · ${esc(item.role)}`:''}${(item.appearance||item.description)?`<small>${esc(item.appearance||item.description)}</small>`:''}</li>`).join('')}</ul></div>`:'';
