async function requestUnderstanding(answers=''){
  const projectId=current.id;
  if(!(current.idea||'').trim()){setPlanNotice('error','Tulis ide terlebih dahulu.');renderTab();return}
  const existing=understandingState();
  if(existing&&!confirm(existing.status==='confirmed'?'Membuat ulang rencana menggantikan rencana yang sudah disetujui. Lanjutkan?':'Membuat ulang rencana menggantikan isian rencana yang belum disetujui. Lanjutkan?'))return;
  if(!(await saveBeforeLeaving()))return;
  packageBusy=true;planNotice=null;renderTab();
  try{
    const result=await api('/api/ai/understanding',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({...aiRequestPayload(),answers})});
    if(current?.id===projectId){current.data.understanding={...result.understanding,status:'draft'};const saved=await saveNow();setPlanNotice(saved?'ok':'error',saved?(result.understanding.questions?.length?'Rencana dibuat. AI punya beberapa pertanyaan singkat, jawab di bawah atau langsung setujui.':'Rencana dibuat. Periksa lalu setujui.'):'Rencana belum tersimpan ke server. Rencana ini masih ada di layar; tekan "Ulangi simpan" di atas sebelum meninggalkan halaman.',projectId)}
  }catch(error){setPlanNotice('error',error.message,projectId)}
  finally{packageBusy=false;if(activeTab==='idea'||activeTab==='package')renderTab()}
}
function updateUnderstandingField(key,value){
  const u=understandingState();
  if(!u||understandingConfirmed())return;
  u[key]=understandingListFields.includes(key)?value.split('\n').map(line=>line.trim()).filter(Boolean):value.trim();
  scheduleSave();
}
async function reopenUnderstanding(){
  const u=understandingState();
  if(!u)return;
  current.data.understanding={...u,status:'draft'};
  await saveNow();
  renderTab();
}
async function buildPackage(){
  const projectId=current.id;
  if(!understandingConfirmed()){toast('Konfirmasi pemahaman ide dulu di langkah 1.');return}
  if(!(await saveBeforeLeaving()))return;
  packageBusy=true;renderTab();
  try{
    const result=await api('/api/ai/production',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({...aiRequestPayload(),model_key:packageModelKey,project_id:projectId,include_images:false})});
    if(current?.id===projectId){packageDraft=result.package;toast('Paket dibuat. Tinjau sebelum menyimpan.')}
  }catch(error){toast(error.message)}
  finally{packageBusy=false;if(activeTab==='package')renderTab()}
}
async function savePackageRecord(pkg,message='Paket produksi tersimpan'){
  const projectId=current.id;
  const request=saveQueue.catch(()=>{}).then(()=>api(`/api/projects/${projectId}/production-package`,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({package:pkg,targetSeconds:packageTargetSeconds()})}));
  saveQueue=request.then(()=>undefined,()=>undefined);
  const saved=await request;
  const view=saved.data?.productionPackage??null;
  const listed=projects.find(p=>p.id===projectId);
  if(listed?.data)listed.data.productionPackage=view;
  if(current?.id===projectId)current.data.productionPackage=view;
  setSaveState(message,projectId);
  return view;
}
async function confirmPackageDraft(){
  if(!packageDraft)return;
  const draft=packageDraft;
  try{
    await savePackageRecord(draft);
    if(packageDraft===draft)packageDraft=null;
    toast('Paket produksi disimpan di proyek ini.');
  }catch(error){setPlanNotice('error',`Paket belum tersimpan: ${String(error.message).replace(/\.\s*$/,'')}. Draf paket di layar ini belum tersimpan; tekan "Simpan paket ke proyek" untuk mencoba lagi.`)}
  renderTab();
}
async function clearPackage(){
  if(!confirm('Hapus paket produksi yang tersimpan di proyek ini? Daftar klip dan prompt akan hilang. Gambar yang sudah diunggah tidak ikut terhapus.'))return;
  try{
    await savePackageRecord(null,'Paket produksi dihapus');
    toast('Paket produksi dihapus dari proyek ini.');
  }catch(error){toast(`Paket belum dihapus: ${error.message}`)}
  renderTab();
}
async function linkRequirement(requirementId,assetId){
  const source=packageForView();
  if(!source)return;
  const next=JSON.parse(JSON.stringify(source));
  const requirement=(next.image_requirements||[]).find(item=>item.id===requirementId);
  if(!requirement)return;
  requirement.asset_id=assetId||null;
  requirement.status=assetId?'uploaded':'needed';
  if(packageDraft){packageDraft=next;renderTab();return}
  try{await savePackageRecord(next,'Tautan gambar disimpan')}
  catch(error){toast(`Tautan belum disimpan: ${error.message}`)}
  renderTab();
}
function copyPackageClip(index,lang){
  const pkg=packageForView();
  const clip=pkg?.clips?.find(item=>item.index===index);
  if(!clip)return;
  const {text}=assemblePromptText(clip,pkg,lang);
  if(text)copy(text);
}
