$('#create-form').onsubmit=async e=>{e.preventDefault();if(!await saveBeforeLeaving())return;const body={title:$('#new-title').value.trim()||'Proyek baru',goal:$('#new-goal').value,idea:$('#new-idea').value.trim(),platform:'flow'};try{const p=await api('/api/projects',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});$('#create-dialog').close();await load();openProject(p.id)}catch(err){toast(err.message)}};
document.addEventListener('click',async e=>{if(visualClick(e))return;const tab=e.target.closest('[data-tab]');if(tab){pendingAdvance=null;setTab(tab.dataset.tab);return}const view=e.target.closest('[data-view]');if(view){if(!await saveBeforeLeaving())return;navigate(view.dataset.view);return}const open=e.target.closest('[data-open]');if(open){if(!await saveBeforeLeaving())return;openProject(open.dataset.open);return}if(e.target.dataset?.linkAll){linkAssetToScenes(ensureData(),e.target.dataset.linkAll,ensureData().scenes.map(scene=>scene.id));scheduleSave();renderTab();toast('Aset ditautkan ke semua adegan.');return}if(e.target.dataset?.deleteAsset){const asset=ensureData().assets.find(item=>item.id===e.target.dataset.deleteAsset);if(!asset)return;const impacted=ensureData().scenes.filter(scene=>(scene.referenceAssetIds||scene.assetIds||[]).includes(asset.id));const detail=impacted.length?`Aset ini digunakan oleh: ${impacted.map(scene=>scene.title||'Adegan tanpa judul').join(', ')}. Referensi akan dilepas.`:'Aset ini belum digunakan oleh adegan.';if(!confirm(`Hapus aset “${asset.name}”? ${detail}`))return;if(!await saveBeforeLeaving())return;try{const result=await api(`/api/projects/${current.id}/assets/${asset.id}`,{method:'DELETE'});current=result.project||current;if(!result.project)removeAssetReferences(ensureData(),asset.id);const index=projects.findIndex(item=>item.id===current.id);if(index>=0)projects[index]=current;saveMessages.set(current.id,'Perubahan tersimpan');renderCards();renderTab();toast('Aset dihapus dan referensi adegan diperbarui.')}catch(error){toast(`Aset belum dihapus: ${error.message}`)}return}if(e.target.id==='build-package'){await buildPackage();return}if(e.target.id==='save-package'){await confirmPackageDraft();return}if(e.target.id==='discard-package'){packageDraft=null;renderTab();return}if(e.target.id==='clear-package'){await clearPackage();return}if(e.target.id==='copy-package-json'){const pkg=packageForView();if(pkg)copy(JSON.stringify(pkg,null,2));return}if(e.target.id==='use-message-suggestion'){const d=ensureData();d.message=d.messageSuggestion||'';d.messageSuggestion='';scheduleSave();renderTab();return}if(e.target.id==='dismiss-message-suggestion'){ensureData().messageSuggestion='';scheduleSave();renderTab();return}if(e.target.id==='build-understanding'){await requestUnderstanding();return}if(e.target.id==='answer-questions'){const answers=($('#plan-answers')?.value||'').trim();if(!answers){setPlanNotice('error','Tulis jawaban singkat dulu, atau setujui rencana ini.');renderTab();return}await requestUnderstanding(answers);return}if(e.target.id==='use-recommended-style'){ensureData().style=e.target.dataset.style;scheduleSave();setPlanNotice('ok','Gaya rekomendasi dipakai.');renderTab();return}if(e.target.id==='confirm-understanding'){await confirmUnderstanding();return}if(e.target.id==='reopen-understanding'){await reopenUnderstanding();return}if(e.target.dataset?.copyClip){copyPackageClip(Number(e.target.dataset.copyClip),e.target.dataset.copyLang||'id');return}if(e.target.id==='retry-save'){if(await saveNow(pendingSave||current))renderProject();return}if(e.target.id==='rename-project'){const name=prompt('Nama proyek',current.title);if(name?.trim()){current.title=name.trim().slice(0,80);if(await saveNow())renderProject()}}if(e.target.id==='delete-project'&&confirm(`Hapus proyek “${current.title}” beserta gambar yang diunggah?`)){if(!await saveBeforeLeaving())return;await api('/api/projects/'+current.id,{method:'DELETE'});current=null;await load();navigate('projects');toast('Proyek dihapus.')}});
async function deleteReferenceAsset(id){
  const projectId=current.id;
  try{
    if(!await saveBeforeLeaving()){toast('Referensi belum dihapus: simpan perubahan dulu.');return}
    const result=await api(`/api/projects/${projectId}/assets/${id}`,{method:'DELETE'});
    if(current?.id===projectId){current=result.project||current;if(!result.project)removeAssetReferences(ensureData(),id);const index=projects.findIndex(p=>p.id===projectId);if(index>=0)projects[index]=current;renderCards();renderTab()}
  }catch(error){toast(`Referensi belum dihapus: ${error.message}`)}
}
async function replaceReference(oldId,file){
  const old=(ensureData().assets||[]).find(a=>a&&a.id===oldId);
  if(!old)return;
  const uploaded=await uploadAssets({target:{files:[file]}},{category:old.type||'Referensi umum',label:old.label||'',entityKind:old.entityKind,entityId:old.entityId,sceneId:old.sceneId});
  if(uploaded.length)await deleteReferenceAsset(oldId);
}
function visualClick(e){
  const t=e.target;
  if(t.id==='add-product'){const d=ensureData();d.entities.products.push({id:entityId('prod'),name:'',description:'',source:'manual'});scheduleSave();renderTab();return true}
  if(!t.dataset?.copyChar&&!t.dataset?.copyScene&&!t.dataset?.copyEntity&&!t.dataset?.resetPrompt)return false;
  const d=ensureData();
  if(t.dataset?.copyChar){const c=d.entities.characters.find(x=>x.id===t.dataset.copyChar);if(c)copy(characterPrompt(c,d));return true}
  if(t.dataset?.copyEntity){copy(entityPromptText(t.dataset.copyEntity,d));return true}
  if(t.dataset?.copyScene){const s=d.scenes.find(x=>x.id===t.dataset.copyScene);if(!s)return true;copy(scenePrompt(s,d));d.visualState['scene:'+s.id]={copiedAt:new Date().toISOString()};scheduleSave();renderTab();return true}
  if(t.dataset?.resetPrompt){delete d.visualPrompts[t.dataset.resetPrompt];scheduleSave();renderTab();return true}
  return false;
}
function visualChange(e){
  const t=e.target, ds=t.dataset||{};
  if(ds.assetLabel===undefined&&ds.refUpload===undefined&&ds.refReplace===undefined&&ds.sceneUpload===undefined&&ds.sceneProduct===undefined)return false;
  const d=ensureData();
  if(ds.assetLabel!==undefined){const a=(d.assets||[]).find(x=>x&&x.id===ds.assetLabel);if(a){a.label=t.value;scheduleSave();renderTab()}return true}
  if(ds.refUpload!==undefined){const kind=ds.refKind,id=ds.refId,entity=(d.entities[kind]||[]).find(x=>x.id===id),label=document.querySelector(`[data-ref-label-select="${kind}:${id}"]`)?.value||entityLabelOptions[kind]?.[0]?.[0];if(entity&&entityCategory[kind]&&t.files?.length)uploadAssets({target:{files:t.files}},{category:entityCategory[kind],label,entityKind:kind,entityId:id});return true}
  if(ds.refReplace!==undefined){if(t.files?.length)replaceReference(ds.refReplace,t.files[0]);return true}
  if(ds.sceneUpload!==undefined){const id=ds.sceneUpload;if(d.scenes.some(x=>x.id===id)&&t.files?.length)uploadAssets({target:{files:t.files}},{category:'Adegan',sceneId:id});return true}
  if(ds.sceneProduct!==undefined){const s=d.scenes.find(x=>x.id===ds.sceneId);if(s){const ids=new Set(s.productIds||[]);if(t.checked)ids.add(ds.sceneProduct);else ids.delete(ds.sceneProduct);s.productIds=[...ids];scheduleSave()}return true}
  return false;
}

function visualInput(e){
  const t=e.target;
  if(t.dataset?.charPrompt===undefined&&t.dataset?.scenePrompt===undefined&&t.dataset?.entityPrompt===undefined)return false;
  const d=ensureData();
  if(t.dataset?.entityPrompt!==undefined){d.visualPrompts[t.dataset.entityPrompt]=t.value;scheduleSave();return true}
  if(t.dataset?.charPrompt!==undefined){d.visualPrompts['char:'+t.dataset.charPrompt]=t.value;scheduleSave();return true}
  if(t.dataset?.scenePrompt!==undefined){d.visualPrompts['scene:'+t.dataset.scenePrompt]=t.value;scheduleSave();return true}
  return false;
}
document.addEventListener('input',e=>{visualInput(e)});
document.addEventListener('toggle',e=>{if(e.target?.classList?.contains('advanced-settings'))advancedSettingsOpen=e.target.open},true);
document.addEventListener('change',e=>{if(visualChange(e))return;if(e.target.dataset?.acceptSuggestion!==undefined)toggleSuggestion(Number(e.target.dataset.acceptSuggestion),e.target.checked);if(e.target.dataset?.linkRequirement!==undefined)linkRequirement(e.target.dataset.linkRequirement,e.target.value);if(e.target.dataset?.understandingField!==undefined)updateUnderstandingField(e.target.dataset.understandingField,e.target.value)});
load().catch(()=>toast('Tidak dapat memuat proyek. Coba muat ulang halaman.'));
